// rc_hud.c - generated by split_c.py from RayCaster.c
#include "rc_priv.h"



//*****************************************************************************
// HUD drawing (top bar y 0..23, bottom bar y 192..239)
//*****************************************************************************
static void DrawHeart(int16_t x, int16_t y, uint32_t c)
{
    Graphics_FillRect(x + 1, y,     x + 5,  y + 1, c);
    Graphics_FillRect(x + 7, y,     x + 11, y + 1, c);
    Graphics_FillRect(x,     y + 2, x + 12, y + 5, c);
    Graphics_FillRect(x + 1, y + 6, x + 11, y + 6, c);
    Graphics_FillRect(x + 2, y + 7, x + 10, y + 7, c);
    Graphics_FillRect(x + 3, y + 8, x + 9,  y + 8, c);
    Graphics_FillRect(x + 4, y + 9, x + 8,  y + 9, c);
    Graphics_FillRect(x + 5, y + 10, x + 7, y + 10, c);
    Graphics_FillRect(x + 6, y + 11, x + 6, y + 11, c);
}


void rc_DrawHudFrame(void)
{
    Graphics_FillRect(0, 0, SCREEN_W - 1, RC_VIEW_Y0 - 1, C_BLACK);
    Graphics_FillRect(0, RC_VIEW_Y1 + 1, SCREEN_W - 1, SCREEN_H - 1, C_BLACK);

    // Side margins around the 3D view are always black.
    if(RC_VIEW_X0 > 0)
        Graphics_FillRect(0, RC_VIEW_Y0, RC_VIEW_X0 - 1, RC_VIEW_Y1, C_BLACK);
    if(RC_VIEW_X0 + RC_VIEW_W <= SCREEN_W - 1)
        Graphics_FillRect(RC_VIEW_X0 + RC_VIEW_W, RC_VIEW_Y0, SCREEN_W - 1, RC_VIEW_Y1, C_BLACK);
}


// Bottom line: what is active, else the controls.
static void DrawHint(void)
{
    char    buf[32];
    int16_t n;

    Graphics_FillRect(0, 217, SCREEN_W - 1, SCREEN_H - 1, C_BLACK);
    if(rc_doorNear)
    {
        uint16_t cost = rc_DoorCost();

        n  = rc_Cat(buf, 0, "DOOR ", 5);
        n += rc_Itoa(buf + n, cost);
        rc_Cat(buf, n, "G - press stick", 15);
        rc_DrawText(buf, SCREEN_W / 2, 229, (rc_gold >= cost) ? C_GREEN : C_BAD);
    }
    else if(rc_aegis) rc_DrawText("SHIELD UP!", SCREEN_W / 2, 229, COLOR_SKY_BLUE);
    else if(rc_haste) rc_DrawText("HASTE!", SCREEN_W / 2, 229, C_GOLD);
    else if(rc_nullify) rc_DrawText("MAGIC WEAKENED!", SCREEN_W / 2, 229, C_XP);
    else if(rc_pSlow)   rc_DrawText("SLOWED!", SCREEN_W / 2, 229, COLOR_SKY_BLUE);
    else             rc_DrawText("U:use  D:swap  L/R:turn", SCREEN_W / 2, 229, C_DKGRAY);
}


void rc_DrawHud(void)
{
    char    buf[24];
    int16_t n, i;

    if(rc_hud & HUD_HEARTS)
    {
        Graphics_FillRect(0, 0, 111, RC_VIEW_Y0 - 1, C_BLACK);
        for(i = 0; i < (int16_t)rc_maxHp; i++)
            DrawHeart(5 + i * 18, 6, (i < (int16_t)rc_hp) ? C_RED : C_DKGRAY);
    }

    if(rc_hud & HUD_TOPR)                    // room, player level, gold, XP bar
    {
        int16_t w;

        Graphics_FillRect(112, 0, SCREEN_W - 1, RC_VIEW_Y0 - 1, C_BLACK);

        if(rc_IsBossLevel(rc_level))
            rc_DrawSmall("BOSS", 140, 8, C_RED, C_BLACK);
        else if(rc_lv.treasure)
            rc_DrawSmall("TREASURE", 140, 8, C_GOLD, C_BLACK);
        else
        {
            n  = rc_Cat(buf, 0, "ROUND ", 6);
            rc_Itoa(buf + n, rc_level + 1);
            rc_DrawSmall(buf, 140, 8, C_WHITE, C_BLACK);
        }

        n  = rc_Cat(buf, 0, "LV ", 3);
        rc_Itoa(buf + n, rc_xpLv);
        rc_DrawSmall(buf, 207, 8, C_XP, C_BLACK);

        n  = rc_Cat(buf, 0, "G ", 2);
        rc_Itoa(buf + n, rc_gold);
        rc_DrawSmall(buf, 280, 8, C_GOLD, C_BLACK);

        Graphics_FillRect(XP_BAR_X0, XP_BAR_Y0, XP_BAR_X1, XP_BAR_Y1, C_DKGRAY);
        Graphics_FillRect(XP_BAR_X0 + 1, XP_BAR_Y0 + 1, XP_BAR_X1 - 1, XP_BAR_Y1 - 1, COLOR_TETRIS_GRID);
        w = (int16_t)(((int32_t)rc_xp * (XP_BAR_X1 - XP_BAR_X0 - 1)) / rc_XpNeed());
        if(w > 0)
            Graphics_FillRect(XP_BAR_X0 + 1, XP_BAR_Y0 + 1, XP_BAR_X0 + w,
                              XP_BAR_Y1 - 1, C_XP);
    }

    if(rc_hud & HUD_STAFF)
    {
        Graphics_FillRect(0, RC_VIEW_Y1 + 2, 189, 215, C_BLACK);
        rc_DrawText(rc_SlotName(rc_equip), 85, 203, rc_SlotColor(rc_equip));
        n  = rc_Cat(buf, 0, "MP ", 3);
        rc_Itoa(buf + n, rc_SlotMana(rc_equip));
        rc_DrawSmall(buf, 165, 204, C_MANA, C_BLACK);
        rc_cdShown = -1;                     // redraw the cooldown strip too
    }

    if(rc_hud & HUD_LEFT)
    {
        Graphics_FillRect(190, RC_VIEW_Y1 + 2, SCREEN_W - 1, 215, C_BLACK);
        if(rc_roundGap)
        {
            n  = rc_Cat(buf, 0, "Next round ", 11);
            rc_Itoa(buf + n, (uint16_t)((rc_roundGap + 29u) / 30u));
            rc_DrawText(buf, 255, 203, C_GREEN);
        }
        else
        {
            int16_t bhp = 0;

            for(i = 0; i < RC_MAX_ENEMIES; i++)         // a mini-boss or the Dragon is alive
                if(rc_en[i].alive && (RC_IS_MINI(rc_en[i].type) || rc_en[i].type == ET_DRAGON))
                    { bhp = rc_en[i].hp; break; }
            if(bhp > 0)
            {
                n  = rc_Cat(buf, 0, "Boss HP ", 8);
                rc_Itoa(buf + n, (uint16_t)bhp);
            }
            else if(rc_lv.treasure)
                rc_Cat(buf, 0, "Find treasure", 13);
            else
            {
                n  = rc_Cat(buf, 0, "Left ", 5);
                rc_Itoa(buf + n, rc_toSpawn + rc_CountRegular());
            }
            rc_DrawText(buf, 255, 203, C_WHITE);
        }
    }

    if(rc_hud & HUD_HINT) DrawHint();

    rc_hud = 0;
}

void rc_DrawCdStrip(void)
{
    uint16_t cd = rc_cd[rc_equip];
    uint16_t mx = rc_cdMax[rc_equip];
    int16_t  w;

    if(cd == 0 || mx == 0) w = CD_STRIP_W;
    else
    {
        w = (int16_t)(CD_STRIP_W - (int16_t)(((int32_t)cd * CD_STRIP_W) / mx));
        if(w < 0) w = 0;
    }

    if(w == rc_cdShown) return;

    if(rc_cdShown >= 0 && w > rc_cdShown && w < CD_STRIP_W)
    {
        // filling up: only the new part
        Graphics_FillRect(CD_STRIP_X0 + rc_cdShown, 213, CD_STRIP_X0 + w - 1, 215, C_GRAY);
    }
    else
    {
        Graphics_FillRect(CD_STRIP_X0, 213, CD_STRIP_X0 + CD_STRIP_W - 1, 215, C_DKGRAY);
        if(w > 0)
            Graphics_FillRect(CD_STRIP_X0, 213, CD_STRIP_X0 + w - 1, 215,
                              (w == CD_STRIP_W) ? rc_SlotColor(rc_equip) : C_GRAY);
    }
    rc_cdShown = w;
}

void rc_DrawManaBar(void)
{
    int16_t  y0 = RC_VIEW_Y0, y1 = RC_VIEW_Y1;
    int16_t  inB = (int16_t)(y1 - 1);                   // bottom inner row
    int16_t  inH = (int16_t)(RC_VIEW_H - 2);
    int16_t  h   = (int16_t)(((int32_t)rc_mana * inH) / MANA_MAX);
    bool     fl  = (rc_manaFlash != 0);
    uint32_t col = fl ? C_RED : C_MANA;

    if(rc_manaFlash) rc_manaFlash--;

    if(h == rc_manaShown && fl == rc_manaFlashShown) return;

    if(rc_manaShown < 0 || fl != rc_manaFlashShown)       // full repaint
    {
        Graphics_FillRect(0, y0, MANA_X1 + 1, y1, C_BLACK);
        Graphics_FillRect(MANA_X0, y0, MANA_X1, y1, C_DKGRAY);
        Graphics_FillRect(MANA_X0 + 1, y0 + 1, MANA_X1 - 1, y1 - 1, COLOR_TETRIS_GRID);
        if(h > 0)
            Graphics_FillRect(MANA_X0 + 1, inB - h + 1, MANA_X1 - 1, inB, col);
    }
    else if(h > rc_manaShown)                            // filled up
        Graphics_FillRect(MANA_X0 + 1, inB - h + 1, MANA_X1 - 1, inB - rc_manaShown, col);
    else                                                // used some
        Graphics_FillRect(MANA_X0 + 1, inB - rc_manaShown + 1, MANA_X1 - 1, inB - h,
                          COLOR_TETRIS_GRID);

    rc_manaShown      = h;
    rc_manaFlashShown = fl;
}
